        <div class="erp-hero mb-3 d-flex flex-column flex-md-row justify-content-between gap-3 align-items-md-center"><div><h3 class="mb-1 fw-bold">Master Jobdesk</h3><div class="opacity-75">Kelola posisi kerja dan kompatibilitas jobdesk legacy.</div></div><button class="btn btn-light fw-semibold" id="btnAdd"><i class="fas fa-plus me-1"></i> Tambah</button></div>
        <div class="erp-panel p-3"><table class="table table-hover align-middle w-100" id="tableJobdesk"><thead><tr><th>Jobdesk</th><th>Deskripsi</th><th>Status</th><th>Aksi</th></tr></thead></table></div>
